<template><view class="extra-audio-settings"><Bi zh="非课内语音包" fr="Audio du dictionnaire"/><Bi zh="用于词库及导入词的单词、例句发音。课内录音已内置。" fr="Mots et phrases du dictionnaire. Audio des leçons déjà intégré." small/><view class="audio-pack-state"><text>{{ statusLabel }}</text><text>{{ size(state.downloaded||0) }} / {{ size(state.total||0) }}</text></view><view class="thin-progress"><view :style="{width:Math.min(100,(state.downloaded||0)/Math.max(1,state.total||1)*100)+'%'}"/></view><text v-if="error||state.error" class="audio-pack-error">{{ error||state.error }}</text><view class="audio-pack-actions"><button v-if="!state.ready" class="button primary" hover-class="none" :disabled="busy||state.state==='checking'||state.state==='installing'" @click="operate(state.running?'pause':'start')"><Icon :name="state.running?'pause':'download'"/><Bi :zh="state.running?'暂停':state.downloaded?'继续下载':'下载语音包'" :fr="state.running?'Pause':'Télécharger'" small/></button><button v-if="state.ready||!state.running&&state.downloaded>0&&state.state!=='checking'&&state.state!=='installing'" class="button secondary" @click="confirmDelete=true"><Icon name="trash"/><Bi zh="删除语音包" fr="Supprimer" small/></button><button class="text-button" :disabled="busy||state.running||state.ready" @click="operate('import')"><Icon name="upload"/><Bi zh="导入本地语音包" fr="Importer un fichier" small/></button></view><view v-if="confirmDelete" class="audio-delete-confirm"><Bi zh="删除语音包？学习记录会保留。" fr="Supprimer le pack ? Vos progrès sont conservés." small/><view class="audio-pack-actions"><button class="button secondary" @click="confirmDelete=false"><Bi zh="取消" fr="Annuler" small/></button><button class="button primary" @click="remove"><Bi zh="删除" fr="Supprimer" small/></button></view></view></view></template>
<script setup>
import {ref,computed,onMounted,onUnmounted} from 'vue';import {extraAudioCall} from '../platform/extra-audio.js';import Bi from './Bi.vue';import Icon from './Icon.vue';
const state=ref({state:'checking',downloaded:0,total:0}),error=ref(''),busy=ref(false),confirmDelete=ref(false);let timer,alive=true,reading=false;
const statusLabel=computed(()=>({checking:'正在检查 · Vérification',missing:'未下载 · À télécharger',connecting:'正在连接 · Connexion',downloading:'正在下载 · Téléchargement',paused:'已暂停 · Pause',verifying:'正在校验 · Vérification',installing:'正在准备 · Préparation',ready:'已就绪 · Prêt',failed:'下载未完成 · À réessayer',invalid:'文件无效 · Fichier invalide',importing:'正在导入 · Importation'}[state.value.state]||state.value.state));
const size=n=>(n/1048576).toFixed(1)+' MB';async function refresh(){if(reading)return;reading=true;try{const value=await extraAudioCall();if(alive){state.value=value;error.value='';}}catch(e){if(alive)error.value=e.message;}finally{reading=false;}}
async function operate(action){if(busy.value)return;busy.value=true;try{const value=await extraAudioCall(action,action==='delete');if(value)state.value=value;error.value='';}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function remove(){await operate('delete');if(!error.value){confirmDelete.value=false;window.dispatchEvent(new Event('qihang-audio-pack-deleted'));}}
onMounted(()=>{refresh();timer=setInterval(refresh,1000);});onUnmounted(()=>{alive=false;clearInterval(timer);});
</script>
<style scoped>.extra-audio-settings{display:flex;flex-direction:column;gap:14px}.audio-pack-state,.audio-pack-actions{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap}.audio-pack-state{font-size:12px;line-height:1.6;color:#8a9db8}.thin-progress{height:4px;background:#e1e8f2;border-radius:4px;overflow:hidden}.thin-progress>view{height:100%;background:#91a8cb;transition:width .3s}.audio-pack-actions>.button{min-height:43px;padding:9px 13px}.audio-pack-error{font-size:12px;color:#b47f88;line-height:1.6}.audio-delete-confirm{border-top:1px solid #dce5f1;padding-top:15px;display:flex;flex-direction:column;gap:12px}</style>
